import pytest

from containers import flatten


def test_flatten_max_depth_one():
    with pytest.raises(ValueError, match="nesting too deep"):
        flatten([1, [2, [3]]], max_depth=1)


def test_flatten_max_depth_default():
    assert flatten([1, [2, [3, 4]], 5], max_depth=8) == [1, 2, 3, 4, 5]


def test_flatten_max_depth_sufficient():
    assert flatten([1, [2, [3, [4]]]], max_depth=4) == [1, 2, 3, 4]


def test_flatten_nested_tuples():
    assert flatten([("a", "b"), ("c",)], max_depth=8) == ["a", "b", "c"]

import pytest

from containers import flatten


def test_flatten_max_depth_one_with_tuple():
    with pytest.raises(ValueError, match="nesting too deep"):
        flatten([1, (2, (3,))], max_depth=1)


def test_flatten_deep_nesting():
    # 8 levels deep should succeed
    deep = [1]
    for _ in range(8):
        deep = [deep]
    assert flatten(deep, max_depth=8) == [1]


def test_flatten_deep_nesting_exceeds_max():
    # 9 levels deep should fail
    deep = [1]
    for _ in range(9):
        deep = [deep]
    with pytest.raises(ValueError, match="nesting too deep"):
        flatten(deep, max_depth=8)


def test_flatten_non_sequence_items():
    assert flatten([1, 2.5, "text", None], max_depth=8) == [1, 2.5, "text", None]

