import pytest
from parsers import parse_kv_pairs

def test_return_type_is_dict():
    result = parse_kv_pairs("a=1,b=2")
    assert isinstance(result, dict)

def test_return_type_is_dict_for_empty_input():
    result = parse_kv_pairs("")
    assert isinstance(result, dict)

def test_return_type_is_dict_for_whitespace_only():
    result = parse_kv_pairs("   \t\n")
    assert isinstance(result, dict)

def test_dict_keys_are_strings():
    result = parse_kv_pairs("a=1,b=2")
    assert all(isinstance(k, str) for k in result.keys())

def test_dict_values_are_strings():
    result = parse_kv_pairs("a=1,b=2")
    assert all(isinstance(v, str) for v in result.values())

def test_dict_values_are_stripped():
    result = parse_kv_pairs("a=  1  ")
    assert result['a'] == '1'

def test_dict_keys_are_stripped():
    result = parse_kv_pairs("  a=1  ")
    assert result['a'] == '1'

